srcDoc.css:
*{box-sizing:border-box}
html,body,#root{margin:0;background:#0d1822;color:#e7eef4;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;font-size:13px}
button{font:inherit;color:inherit;cursor:pointer}
.num{font-variant-numeric:tabular-nums}
.app{display:flex;flex-direction:column;padding:10px;gap:10px;position:relative}
.bar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;background:#132230;border:1px solid #1f3346;border-radius:10px;padding:10px 12px}
.bar h1{font-size:16px;margin:0 8px 0 0;font-weight:600}
.pill{font-size:11px;padding:2px 8px;border-radius:999px;background:#2a2f14;color:#e6d27a;border:1px solid #5a5220}
.bar label{font-size:12px;color:#8ea3b5;display:flex;align-items:center;gap:6px}
select,input[type=text],textarea{background:#0d1822;color:#e7eef4;border:1px solid #2a4258;border-radius:6px;padding:5px 8px;font:inherit}
.tog{display:inline-flex;align-items:center;gap:6px;background:#0d1822;border:1px solid #2a4258;border-radius:999px;padding:4px 10px;font-size:12px}
.tog.on{border-color:#3987e5;color:#cfe2fb}
.tog .sw{width:8px;height:8px;border-radius:50%;background:#4a5d70}
.tog.on .sw{background:#3987e5}
.spacer{flex:1}
.main{display:grid;grid-template-columns:minmax(300px,36%) 1fr;gap:10px;align-items:start}
.pane{background:#132230;border:1px solid #1f3346;border-radius:10px;display:flex;flex-direction:column;min-height:0;overflow:hidden}
.pane-h{padding:10px 12px;border-bottom:1px solid #1f3346;display:flex;align-items:center;gap:8px}
.pane-h b{font-size:13px}
.pane-h .sub{color:#8ea3b5;font-size:12px}
.scroll{overflow:auto;max-height:880px}
.row{display:flex;align-items:center;gap:8px;padding:7px 10px;border-bottom:1px solid #182a3a;cursor:pointer}
.row:hover{background:#17293a}
.row.sel{background:#1b3247}
.row .caret{width:14px;color:#6f8699;font-size:10px;text-align:center}
.row .lbl{flex:1;min-width:0}
.row .lbl .t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.row .lbl .s{font-size:11px;color:#8ea3b5;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.row.l1{padding-left:28px}
.row.l2{padding-left:50px}
.row.muted{cursor:default;color:#8ea3b5}
.dot{width:10px;height:10px;border-radius:50%;background:#fab219;box-shadow:0 0 0 2px #132230;flex:none}
.dot.sev-c{background:#d03b3b}.dot.sev-s{background:#ec835a}.dot.sev-w{background:#fab219}
.dot.hot{box-shadow:0 0 0 2px #132230,0 0 0 4px rgba(231,238,244,.18)}
.dot.off{visibility:hidden}
.cnt{font-size:11px;min-width:22px;text-align:center;padding:1px 6px;border-radius:999px;background:#1a2b3b;color:#c9d6e0;border:1px solid #2a4258}
.cnt.grey{background:#1a2733;color:#8ea3b5;border-color:#2a4258}
.empty{padding:24px;color:#8ea3b5;text-align:center}
.right{display:flex;flex-direction:column;gap:10px}
.tabs{display:flex;gap:6px;flex-wrap:wrap}
.tab{background:#0d1822;border:1px solid #2a4258;border-radius:6px;padding:4px 10px;font-size:12px}
.tab.on{background:#1f4a73;border-color:#3b82c4}
.tab .n{color:#8ea3b5;margin-left:5px}
.tab.on .n{color:#cfe2fb}
.chartbox{padding:8px 12px 12px}
svg text{fill:#8ea3b5;font-size:11px}
.leg{display:flex;gap:14px;font-size:11px;color:#8ea3b5;padding:0 12px 8px;flex-wrap:wrap}
.leg i{display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:5px;vertical-align:-1px}
.hot{cursor:pointer}
.cards{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:8px;padding:10px 12px}
.card{background:#0f1d29;border:1px solid #243a50;border-left:3px solid #fab219;border-radius:8px;padding:9px 10px;cursor:pointer}
.card.sev-c{border-left-color:#d03b3b}.card.sev-s{border-left-color:#ec835a}.card.sev-w{border-left-color:#fab219}
.card:hover{background:#142636}
.card.ack{border-left-color:#4a5d70;opacity:.6}
.card.flag{border-left-color:#9085e9}
.card .c1{display:flex;gap:6px;align-items:center;font-size:11px;color:#8ea3b5}
.card .c2{margin:4px 0 3px;font-weight:600}
.card .c3{font-size:11px;color:#8ea3b5}
.chip{font-size:10px;padding:1px 6px;border-radius:4px;background:#1a2733;border:1px solid #2a4258;color:#b9c9d6}
.chip.st-open{color:#e7eef4}
.chip.st-ack{color:#8ea3b5}
.chip.st-flag{border-color:#9085e9;color:#e7eef4;background:#221f3d}
.chip.st-res{border-color:#0ca30c;color:#e7eef4;background:#0f2a1a}
.tt{position:fixed;z-index:50;pointer-events:none;background:#06101a;border:1px solid #2a4258;border-radius:6px;padding:7px 9px;font-size:12px;white-space:pre-line;max-width:360px;opacity:0;transition:opacity .08s}
.ov{position:absolute;left:0;top:0;right:0;background:rgba(3,8,14,.66);display:flex;justify-content:center;align-items:flex-start;z-index:40;padding:20px}
.modal{background:#132230;border:1px solid #2a4258;border-radius:12px;width:min(760px,100%);max-height:720px;display:flex;flex-direction:column}
.modal .mh{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid #1f3346}
.modal .mh b{flex:1;font-size:14px}
.modal .mb{overflow:auto;padding:10px 14px;display:flex;flex-direction:column;gap:10px}
.note{font-size:11px;color:#e6d27a;background:#2a2f14;border:1px solid #5a5220;border-radius:6px;padding:6px 9px}
.grp{background:#0f1d29;border:1px solid #243a50;border-radius:8px;padding:10px 12px}
.grp .gh{display:flex;gap:8px;align-items:center;flex-wrap:wrap}
.grp .gh b{font-size:13px}
.kv{display:grid;grid-template-columns:130px 1fr;gap:3px 10px;margin:8px 0;font-size:12px}
.kv span:nth-child(odd){color:#8ea3b5}
.msgs{font-size:12px;color:#c9d6e0;margin:6px 0;padding-left:16px}
.hist{font-size:11px;color:#8ea3b5;margin:4px 0 0;padding-left:16px}
.acts{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:8px}
.btn{border:1px solid #2a4258;background:#0d1822;border-radius:6px;padding:5px 12px;font-size:12px}
.btn.pri{background:#1f4a73;border-color:#3b82c4}
.btn.flag.pri{background:#2c2658;border-color:#9085e9}
.btn.link{border:none;background:none;color:#7cb8f0;padding:0;text-decoration:underline}
.x{background:none;border:none;font-size:18px;color:#8ea3b5}
textarea{width:100%;min-height:54px;margin-top:6px}
.sev{display:inline-flex;align-items:center;gap:5px;font-size:11px;color:#c9d6e0}
.sev i{width:8px;height:8px;border-radius:50%;display:inline-block}
.chip .g{color:#8ea3b5;margin-right:3px}
.row.l3{padding-left:72px}
.row.l4{padding-left:94px}
.row.l4 .t{font-size:12px}
.swl{width:4px;height:22px;border-radius:2px;flex:none}
.filters{display:flex;align-items:center;gap:8px;flex-wrap:wrap;width:100%;padding-top:8px;border-top:1px solid #1f3346}
.filters select{font-size:12px;padding:4px 6px}
.flbl{font-size:12px;color:#8ea3b5}
.leg .lgh{color:#8ea3b5}
.lg{display:inline-flex;align-items:center;gap:6px;background:none;border:1px solid transparent;border-radius:6px;padding:2px 6px;font-size:11px;color:#c9d6e0}
button.lg:hover{border-color:#2a4258}
.lg i{width:14px;height:3px;border-radius:2px;margin:0}
.lg.off{color:#5d7488;text-decoration:line-through}
.lg.off i{opacity:.3}
.flagform{margin-top:8px}
.flagform label{font-size:12px;color:#8ea3b5;display:flex;align-items:center;gap:8px}

