function popupHtml(gs){
  if(!S.popup) return "";
  var keys=S.popup, list=gs.filter(function(g){ return keys.indexOf(g.key)>=0; });
  if(!list.length){ S.popup=null; return ""; }
  var allIts=(function(){ var save=S.sel; S.sel=null; var x=items(); S.sel=save; return x; })();
  var vas=vaById();
  var cust=((M.customers||[]).filter(function(c){ return String(c.id)===String(M.customerId); })[0]||{}).name;
  var loc=((M.locations||[]).filter(function(l){ return String(l.location_id)===String(M.locationId); })[0]||{}).name;
  var body=list.map(function(g){
    var todo=TODO[g.code]||"either";
    var msgs={}; g.rows.forEach(function(r){ if(r.message) msgs[r.message]=true; });
    var ml=Object.keys(msgs);
    var d=(g.rows[0]&&g.rows[0]._d)||{};
    var kv=[];
    function add(k,v){ if(v!=null&&v!==""&&v!=="—") kv.push([k,v]); }
    var gva=Object.keys(g.va).map(function(v){ return vas[v]; }).filter(Boolean);
    add("Customer",cust);
    add("Location",loc);
    add("Account",uniq(gva.map(acctKey)).join(", ")||g.account);
    add("Vendor",uniq(gva.map(function(a){ return a.vendor; })).join(", ")||g.vendor);
    add("Meter",uniq(Object.keys(g.meters).concat(Object.keys(g.meters).length?[]:gva.map(function(a){ return a.meter_serial; }))).join(", "));
    add("Utility",d.commodity||uniq(gva.map(function(a){ return a.commodity; })).join(", "));
    add("Bill",(g.bill_id||"")+(g.invoice_d?"  ·  invoice "+fmtD(day(g.invoice_d)):""));
    var mine=allIts.filter(function(i){ return String(i.record)===String(g.record_id); });
    if(mine.length){ var s=Math.min.apply(null,mine.map(function(i){return i.s;})), e=Math.max.apply(null,mine.map(function(i){return i.e||i.s;})); add("Service period",fmtD(s)+" – "+fmtD(e)); }
    add("Type",TYPE[g.code]?TYPE[g.code]:(TYPE_PROPOSED[g.code]?TYPE_PROPOSED[g.code]+" (proposed)":""));
    add("Level",levelOf(g)+(g.meta!=null&&String(g.meta).match(/[a-z_]+/)?" (from definition)":" (from stored data)"));
    add("Validator",g.category);
    if(g.assignee) add("Bill assigned to",g.assignee+(g.assign_d?"  ·  since "+fmtD(day(g.assign_d)):"")+"  (in UBM)");
    add("Stage",stageLbl(g.stage));
    add("Severity",uniq(g.rows.map(function(r){return String(r.severity);})).join(", "));
    if(g.place==="chart"){
      var u=CHART_UNIT[g.code], p=pointFor(g,allIts);
      if(p){ var v=p.v[u], pv=p.prior?p.prior.v[u]:null; add(unitLbl(u)+" this bill",fmtV(v,u,p.uom)); if(pv!=null) add("Prior bill",fmtV(pv,u,p.prior.uom)+"  (bill "+(p.prior.bill_id||"—")+")"); if(v!=null&&pv) add("Change",((v-pv)/Math.abs(pv)*100).toFixed(1)+"%"); }
    }
    if(g.place==="timeline"){
      var r=timelineRange(g,allIts);
      if(r){ add("Affected dates",fmtD(r.s)+" – "+fmtD(r.e)+"  ("+Math.round((r.e-r.s)/DAY+1)+" days, "+r.how+")"); if(r.before&&r.before!==r.after) add("Bill before",(r.before.bill_id||"")+"  "+fmtD(r.before.s)+" – "+fmtD(r.before.e)); if(r.after) add("Bill after",(r.after.bill_id||"")+"  "+fmtD(r.after.s)+" – "+fmtD(r.after.e)); }
    }
    if(g.place==="dot"&&DOT[g.code]==="meter") add("Meter / account",[d.meter_serial,d.account_code].filter(Boolean).join(" / "));
    var er=expectedRange(g), eu=CHART_UNIT[g.code];
    if(er){ add("Bill block value",fmtV(er.v,eu)); add("Expected range",fmtV(er.lo,eu)+" – "+fmtV(er.hi,eu)); }
    var rd=reportedDays(g); if(rd!=null) add("Reported",rd+"-day "+(TIMELINE[g.code]||""));
    if(d.bill_id!=null) add(TIMELINE[g.code]?"Other bill":"Compared with bill",String(d.bill_id));
    if(d.bill_ids) add("Duplicate of bill",arr(d.bill_ids).join(", "));
    if(d.rate_code) add("Rate code",d.rate_code);
    if(d.amount!=null) add("Amount","$"+Number(d.amount).toLocaleString());
    if(d.vendor_code) add("Vendor code",d.vendor_code);
    if(d.client_account) add("Client billing ID",d.client_account);
    if(d.service_address) add("Service address / zip",d.service_address);
    if(d.remittance_address) add("Remittance address",d.remittance_address);
    if(d.bill_type) add("Bill type",d.bill_type);
    if(d.billing_line_items) add("Line items",arr(d.billing_line_items).map(function(x){ return (x&&(x.description||x.code))||""; }).filter(Boolean).join(", "));
    if(d.code&&g.code===2021) add("Missing field",d.code);
    var hist=['Raised '+esc(fmtD(day(g.rows[0].raised)))+(g.rows.length>1?" ("+g.rows.length+" bill blocks)":"")].concat((S.log[g.key]||[]).map(esc));
    var ackBtn='<button class="btn'+(todo==="accept"?" pri":"")+'" data-act="ack" data-g="'+esc(g.key)+'">Acknowledge</button>';
    var flagBtn='<button class="btn flag'+(todo==="escalate"?" pri":"")+'" data-act="flag" data-g="'+esc(g.key)+'">⚑ Flag to operator</button>';
    var acts;
    if(g.status==="res") acts='<span class="chip st-res">✓ Resolved in UBM</span>';
    else if(g.status==="ack") acts='<button class="btn pri" data-act="reflag" data-g="'+esc(g.key)+'">Re-flag</button>';
    else if(g.status==="flag") acts='<span class="chip st-flag">⚑ With operator</span>';
    else acts=ackBtn+flagBtn;
    var ops=M.operators||[];
    var draft=S.flagDraft===g.key?'<div class="flagform"><label>Assign to <select id="flagto">'+opt("",g.assignee?"Current assignee ("+g.assignee+")":"Customer\'s default operator","")+ops.map(function(o){ return opt(o.id,(o.name||"").trim()||o.email,""); }).join("")+'</select></label>'+
      '<textarea id="flagnote" placeholder="Note for the operator (optional)"></textarea><div class="acts"><button class="btn flag pri" data-act="flagok" data-g="'+esc(g.key)+'">Send flag</button><button class="btn" data-act="flagcancel">Cancel</button></div></div>':"";
    return '<div class="grp"><div class="gh"><b>'+g.code+' · '+esc(codeName(g))+'</b>'+statusChip(g)+placeChip(g)+'<span class="sev"><i style="background:'+sevCol(g.maxSev)+'"></i>Severity '+g.maxSev+'</span>'+(TODO[g.code]?'<span class="chip">Default: '+({accept:"Accept",escalate:"Escalate",either:"Either"}[todo])+'</span>':'')+'</div>'+
      '<div class="kv">'+kv.map(function(x){ return '<span>'+esc(x[0])+'</span><span class="num">'+esc(x[1])+'</span>'; }).join("")+'</div>'+
      (ml.length?'<ul class="msgs">'+ml.slice(0,5).map(function(m){return '<li>'+esc(m)+'</li>';}).join("")+(ml.length>5?'<li>+'+(ml.length-5)+' more</li>':'')+'</ul>':'')+
      '<ul class="hist">'+hist.map(function(h){return '<li>'+h+'</li>';}).join("")+'</ul>'+
      '<div class="acts">'+acts+(g.bill_id?'<span class="spacer" style="flex:1"></span><button class="btn link" data-open="'+esc(g.bill_id)+'">Open bill '+esc(g.bill_id)+'</button>':'')+'</div>'+draft+'</div>';
  }).join("");
  // The widget grows to its content and the page scrolls, so a centred overlay
  // could land off-screen; the popup opens level with the click instead.
  var docH=Math.max(document.documentElement.scrollHeight,document.body.scrollHeight);
  var top=Math.max(0,Math.min((S.popY||0)-120,docH-760));
  return '<div class="ov" id="ov" style="height:'+docH+'px;padding-top:'+top+'px"><div class="modal"><div class="mh"><b>'+(list.length===1?"Validation error":list.length+" validation errors")+'</b><button class="x" id="closepop">×</button></div>'+
    '<div class="mb"><div class="note">Prototype: Acknowledge and Flag are kept in this browser tab only and are not saved to UBM.</div>'+body+'</div></div></div>';
}

// ---- actions ---------------------------------------------------------------------
function findGroup(key){ return groups().filter(function(g){ return g.key===key; })[0]; }
function stamp(){ var d=new Date(); return (d.getMonth()+1)+"/"+d.getDate()+" "+d.toTimeString().slice(0,5); }
// Every action goes out as one event with everything a backend call needs;
// the page decides whether it can be saved.
function emit(action,g,extra){
  var p={action:action, errorIds:g.ids, code:g.code, recordId:g.record_id, billId:g.bill_id,
         customerId:M.customerId, locationId:M.locationId, accounts:g.acctKeys};
  for(var k in (extra||{})) p[k]=extra[k];
  send("onErrorAction",{errorAction:p});
}
function act(kind,key){
  var g=findGroup(key); if(!g) return;
  var log=S.log[key]||(S.log[key]=[]);
  if(kind==="ack"){ g.ids.forEach(function(i){ S.ack[i]=true; }); log.push("Acknowledged (muted) "+stamp()+" · not saved"); emit("acknowledge",g); }
  if(kind==="reflag"){ g.ids.forEach(function(i){ delete S.ack[i]; }); log.push("Re-flagged "+stamp()+" · not saved"); emit("reopen",g); }
  if(kind==="flag"){ S.flagDraft=key; }
  if(kind==="flagok"){
    var n=(document.getElementById("flagnote")||{}).value||"";
    var sel=document.getElementById("flagto"), to=sel&&sel.value?Number(sel.value):null, toName=sel&&sel.value?sel.options[sel.selectedIndex].text:"default operator";
    g.ids.forEach(function(i){ S.flag[i]=true; delete S.ack[i]; });
    log.push("Flagged to "+toName+" "+stamp()+(n?": “"+n+"”":"")+" · not saved"); S.flagDraft=null;
    emit("escalate",g,{assigneeId:to,note:n});
  }
  if(kind==="flagcancel"){ S.flagDraft=null; }
  render();
}

function bind(){
  var $=function(id){ return document.getElementById(id); };
