function nameOf(code){ return DEF_NAMES[code]||NAMES[code]||""; }
function summaryByLoc(){
  var out={}, rows=M.summary||[];
  rows.forEach(function(r){ if(r.def_name) DEF_NAMES[r.code]=r.def_name; });
  if(rows.length&&String(rows[0].cust)!==String(M.customerId)) return out;
  rows.forEach(function(r){
    if(!codeOk(Number(r.code))) return;
    var k = r.location_id==null ? "none" : String(r.location_id);
    var o = out[k] || (out[k]={n:0,codes:{},sev:0});
    var n = Number(r.n)||0; o.n+=n; o.codes[r.code]=(o.codes[r.code]||0)+n; o.sev=Math.max(o.sev,Number(r.max_sev)||0);
  }); return out;
}
function fresh(rows){ return (rows||[]).length===0 || String(rows[0].loc)===String(M.locationId); }
function accounts(){ return fresh(M.accounts) ? (M.accounts||[]) : []; }
function bills(){ return fresh(M.bills) ? (M.bills||[]) : []; }
function errorRows(){ return fresh(M.errors) ? (M.errors||[]) : []; }
function vaById(){ var o={}; accounts().forEach(function(a){ o[a.va_id]=a; }); return o; }

function groups(){
  var by={}, list=[];
  errorRows().forEach(function(r){
    var code=Number(r.code), key=r.record_id+"|"+code;
    var g=by[key];
    if(!g){ g=by[key]={key:key,code:code,name:r.def_name,stage:r.stage,record_id:r.record_id,bill_id:r.bill_id,
      invoice_d:r.invoice_d,vendor:r.vendor,account:r.client_account,rows:[],va:{},meters:{},maxSev:0,
      meta:r.def_meta,category:r.def_category||r.category,d:null,
      assignee:(String(r.assign_text||"").match(/assigned to (.+?)\s*$/i)||[])[1]||null,assign_d:r.assign_d,
      place:placement(code),mapped:isMapped(code)}; list.push(g); }
    var d=obj(r.data); r._d=d; if(!g.d) g.d=d;
    g.rows.push(r); g.maxSev=Math.max(g.maxSev,Number(r.severity)||0);
    arr(r.va_ids).forEach(function(v){ g.va[v]=true; });
    if(d.meter_serial) g.meters[d.meter_serial]=true;
  });
  var vas=vaById();
  list.forEach(function(g){
    g.ids=g.rows.map(function(r){return r.error_id;});
    var acked=g.ids.every(function(i){return S.ack[i];});
    var flagged=g.ids.some(function(i){return S.flag[i];});
    var resolved=g.rows.every(function(r){return r.resolved===true||r.resolved==="true"||r.resolved==="t";});
    g.status = flagged?"flag":(resolved?"res":(acked?"ack":"open"));
    // Pin the error with the keys it stores: the exact virtual account, else
    // the meter, account, billing id or vendor. Each step only narrows when it
    // still matches something at this location.
    var d=g.d||{}, ms=Object.keys(g.meters);
    function narrow(test){ var n={}; Object.keys(g.va).forEach(function(v){ if(vas[v]&&test(vas[v])) n[v]=true; }); if(Object.keys(n).length) g.va=n; }
    if(d.virtual_account_id!=null) narrow(function(a){ return String(a.va_id)===String(d.virtual_account_id); });
    if(ms.length) narrow(function(a){ return ms.indexOf(a.meter_serial)>=0; });
    if(d.account_code) narrow(function(a){ return a.account_code===d.account_code; });
    if(d.client_account) narrow(function(a){ return a.client_account===d.client_account||a.account_code===d.client_account; });
    if(d.vendor_code) narrow(function(a){ return a.vendor_code===d.vendor_code; });
    g.acctKeys=uniq(Object.keys(g.va).map(function(v){ return vas[v]?acctKey(vas[v]):null; }));
  });
  return list;
}
function stateOk(g){
  var f=S.f.state;
  if(f==="all") return true;
  if(f==="active") return g.status==="open"||g.status==="flag";
  return g.status===f;
}
function visible(g){
  if(!S.all&&g.status!=="flag") return false;
  if(!stateOk(g)||!codeOk(g.code)) return false;
  if(S.f.stage&&g.stage!==S.f.stage) return false;
  return true;
}

// ---- hierarchy: Location > Account > Vendor > Meter > Bill ----------------------
function acctKey(a){ return a.account_code||("VA "+a.va_id); }
function vendKey(a){ return acctKey(a)+"|"+(a.vendor_code||a.vendor||"?"); }
function tree(){
  var accts={}, order=[];
  accounts().forEach(function(a){
    var k=acctKey(a);
    var t=accts[k]; if(!t){ t=accts[k]={key:k,vendors:{},vorder:[],vas:[],comms:{}}; order.push(t); }
    var vk=vendKey(a), v=t.vendors[vk]; if(!v){ v=t.vendors[vk]={key:vk,name:a.vendor||a.vendor_code||"Unknown vendor",vas:[]}; t.vorder.push(v); }
    v.vas.push(a); t.vas.push(a); if(a.commodity) t.comms[a.commodity]=true;
  });
  order.sort(function(a,b){ return String(a.key).localeCompare(String(b.key)); });
  return order;
}
// stable colour per account: alphabetical order within the location, so a
// filter or selection never repaints an account
function acctColors(){ var o={}; tree().forEach(function(t,i){ o[t.key]=i<COL.lines.length?COL.lines[i]:COL.extra; }); return o; }
function selVas(){
  if(!S.sel) return null;
  var set={};
  if(S.sel.kind==="meter"){ set[S.sel.va]=true; return set; }
  tree().forEach(function(t){
    if(S.sel.kind==="acct"&&t.key===S.sel.acct) t.vas.forEach(function(v){ set[v.va_id]=true; });
    if(S.sel.kind==="vend") t.vorder.forEach(function(v){ if(v.key===S.sel.vend) v.vas.forEach(function(x){ set[x.va_id]=true; }); });
  });
  return set;
}
function inSet(g,vs){ if(!vs) return true; return Object.keys(g.va).some(function(v){ return vs[v]; }); }
function setOf(vas){ var s={}; vas.forEach(function(v){ s[v.va_id]=true; }); return s; }

// ---- chart series ------------------------------------------------------------
function calcVal(calcs,re,notRe){
  var best=null; arr(calcs).forEach(function(c){ var n=String(c.n||c.name||""); if(re.test(n)&&!(notRe&&notRe.test(n))){ var v=num(c.v!=null?c.v:c.value); if(v!=null) best=best==null?v:Math.max(best,v); } }); return best;
}
function items(){
  var vs=selVas(), vas=vaById();
  return bills().filter(function(b){ return !vs || vs[b.va_id]; }).map(function(b){
    var va=vas[b.va_id]||{};
    return {bill:b.bill_id||("R"+b.record_id), bill_id:b.bill_id, record:b.record_id, va:b.va_id,
      acct:va.va_id!=null?acctKey(va):(b.account_code||"?"), comm:(b.commodity||"").toUpperCase(),
      s:day(b.start_d), e:day(b.end_d), inv:b.invoice_d, charges:num(b.charges), total:num(b.bill_total), usage:num(b.usage), uom:b.uom,
      demand:calcVal(b.calcs,/demand/i,/charge|cost|rate|\$/i), lf:calcVal(b.calcs,/load.?factor/i)};
  }).filter(function(i){ return i.s!=null; });
}
function commodities(its){ var c={}; its.forEach(function(i){ if(i.comm) c[i.comm]=(c[i.comm]||0)+1; }); return Object.keys(c).sort(function(a,b){ return (b==="ELECTRIC")-(a==="ELECTRIC") || c[b]-c[a]; }); }
function monthOf(i){ var d=new Date(((i.s)+(i.e!=null?i.e:i.s))/2); return d.getUTCFullYear()*100+d.getUTCMonth(); }
// Chart: one series per account, one point per service month. An account can
// hold several bills a month (supply and distribution vendors, several
// meters); totalling them per month keeps each account a single clean line.
function seriesByAccount(its,comm){ return seriesBy(its,comm,function(i){ return i.acct; },monthOf,true); }
// Popup: the validation compares a bill with the prior bill on the same meter,
// so the comparison uses one series per meter and one point per bill.
function seriesByMeter(its,comm){ return seriesBy(its,comm,function(i){ return String(i.va); },function(i){ return i.bill; },false); }
function seriesBy(its,comm,serKey,ptKey,monthly){
  var byA={}, order=[];
  its.filter(function(i){ return i.comm===comm; }).forEach(function(i){
    var sk=serKey(i), sr=byA[sk]; if(!sr){ sr=byA[sk]={acct:i.acct,key:sk,pts:[],by:{}}; order.push(sr); }
    var pk=ptKey(i), p=sr.by[pk]; if(!p){ p=sr.by[pk]={acct:i.acct,bill:i.bill,bill_id:i.bill_id,bills:[],month:monthly?pk:null,records:{},vas:{},s:i.s,e:i.e,charges:null,total:null,usage:null,uom:i.uom,demand:null,lf:null}; sr.pts.push(p); }
    if(p.bills.indexOf(i.bill_id)<0&&i.bill_id!=null) p.bills.push(i.bill_id);
    var firstOfRecord=!p.records[i.record];
    p.records[i.record]=true; p.vas[i.va]=true; p.s=Math.min(p.s,i.s); if(i.e!=null) p.e=Math.max(p.e||i.e,i.e);
    if(i.charges!=null) p.charges=(p.charges||0)+i.charges;
    if(i.total!=null&&i.charges==null&&firstOfRecord) p.total=(p.total||0)+i.total;
    if(i.usage!=null) p.usage=(p.usage||0)+i.usage;
    if(i.demand!=null) p.demand=Math.max(p.demand||0,i.demand);
    if(i.lf!=null) p.lf=i.lf;
  });
  order.forEach(function(sr){
    sr.pts.forEach(function(p){ if(p.e==null) p.e=p.s;
      p.m = p.month!=null ? Date.UTC(Math.floor(p.month/100),p.month%100,15) : (p.s+p.e)/2;
      var c=(p.charges!=null||p.total!=null)?(p.charges||0)+(p.total||0):null;
      p.v={"$":c, usage:p.usage, demand:p.demand, lf:p.lf, unit:(c!=null&&p.usage)?c/p.usage:null}; });
    sr.pts.sort(function(a,b){ return a.s-b.s; });
    sr.pts.forEach(function(p,i){ p.prior=i>0?sr.pts[i-1]:null; });
  });
  order.sort(function(a,b){ return String(a.acct).localeCompare(String(b.acct)); });
  return order;
}
function pointFor(g,its){
  var cm=null; its.forEach(function(i){ if(!cm&&String(i.record)===String(g.record_id)) cm=i.comm; });
  if(!cm) return null;
  var hit=null; seriesByMeter(its,cm).forEach(function(sr){ sr.pts.forEach(function(p){ if(!hit&&p.records[g.record_id]) hit=p; }); });
  return hit;
}
// service-date ranges come from the neighbouring bill on the same account
// The error stores the other bill it was compared with (data.bill_id) and the
// message states the day count; the range is drawn between that bill pair.
function reportedDays(g){ var m=String((g.rows[0]||{}).message||"").match(/(\d+)-day (gap|overlap)/); return m?Number(m[1]):null; }
function timelineRange(g,its){
  var kind=TIMELINE[g.code], out=null, other=(g.d||{}).bill_id;
  Object.keys(g.va).forEach(function(va){
    var mine=its.filter(function(i){ return String(i.va)===String(va); }).sort(function(a,b){ return a.s-b.s; });
    var cur=mine.filter(function(i){ return String(i.record)===String(g.record_id); })[0];
    var oth=other!=null?mine.filter(function(i){ return String(i.bill_id)===String(other); })[0]:null;
    if(!out&&cur&&oth&&cur.e!=null&&oth.e!=null){
      var a=oth.s<=cur.s?oth:cur, b=a===oth?cur:oth;
      if(kind==="gap"&&b.s-a.e>DAY) out={s:a.e+DAY,e:b.s-DAY,before:a,after:b,how:"between this bill and bill "+other};
      else if(kind==="overlap"&&a.e>=b.s) out={s:b.s,e:Math.min(a.e,b.e),before:a,after:b,how:"between this bill and bill "+other};
      else if(kind==="read") out={s:cur.s,e:cur.e,before:oth,after:cur,how:"this bill's service period; prior reading on bill "+other};
    }
    mine.forEach(function(it,idx){
      if(String(it.record)!==String(g.record_id)||out) return;
      var prev=idx>0?mine[idx-1]:null, next=idx<mine.length-1?mine[idx+1]:null;
      if(kind==="gap"&&prev&&prev.e!=null&&it.s-prev.e>DAY) out={s:prev.e+DAY,e:it.s-DAY,before:prev,after:it,how:"computed from neighbouring bills"};
      else if(kind==="gap"&&next&&it.e!=null&&next.s-it.e>DAY) out={s:it.e+DAY,e:next.s-DAY,before:it,after:next,how:"computed from neighbouring bills"};
      else if(kind==="overlap"&&prev&&prev.e!=null&&prev.e>=it.s) out={s:it.s,e:prev.e,before:prev,after:it,how:"computed from neighbouring bills"};
      else if(kind==="overlap"&&next&&it.e!=null&&it.e>=next.s) out={s:next.s,e:it.e,before:it,after:next,how:"computed from neighbouring bills"};
      else out={s:it.s,e:it.e!=null?it.e:it.s,before:prev,after:it,how:kind==="read"?"flagged bill's service period":"service period (neighbouring bill not found)"};
    });
  });
  return out;
}

function expectedRange(g){
  if(!RANGE_CHECK[g.code]) return null;
  var msg=String((g.rows[0]||{}).message||"").replace(/,/g,"");
  var m=msg.match(/of \$?(-?[\d.]+) is not within the expected range of \$?(-?[\d.]+) - \$?(-?[\d.]+)/);
  return m?{v:Number(m[1]),lo:Number(m[2]),hi:Number(m[3])}:null;
}

// ---- outgoing events ----------------------------------------------------------
// The value travels as the event payload (a variable in the handler) and is
// also written to the model as a fallback; the model alone can be reset
// before the handler reads it.
function send(ev,patch){ appsmith.updateModel(patch); appsmith.triggerEvent(ev,patch); }

// ---- render -------------------------------------------------------------------
function render(){
  var root=document.getElementById("root"); if(!root) return;
  var keepScroll={}; Array.prototype.forEach.call(root.querySelectorAll("[data-keep]"),function(el){ keepScroll[el.getAttribute("data-keep")]=el.scrollTop; });
  var sum=summaryByLoc();
  var gs=groups();
  var shown=gs.filter(visible);
  root.innerHTML='<div class="app">'+topBar(gs,sum)+'<div class="main">'+leftPane(sum,shown)+rightPane(gs,shown)+'</div></div>'+popupHtml(gs);
  Array.prototype.forEach.call(root.querySelectorAll("[data-keep]"),function(el){ var k=el.getAttribute("data-keep"); if(keepScroll[k]) el.scrollTop=keepScroll[k]; });
  bind();
}

function opt(v,l,cur){ return '<option value="'+esc(v)+'"'+(String(v)===String(cur)?" selected":"")+'>'+esc(l)+'</option>'; }
function topBar(gs,sum){
  var opts='<option value="">Select a customer…</option>'+(M.customers||[]).map(function(c){ return opt(c.id,c.name,M.customerId); }).join("");
  var mo=[6,12,24].map(function(n){ return opt(n,"Last "+n+" months",Number(M.months)||12); }).join("");
  // filter choices come from the data on screen: codes and stages present,
  // plus every Type the catalogue knows
  var codes={}; (M.summary||[]).forEach(function(r){ codes[r.code]=codes[r.code]||nameOf(r.code); });
  gs.forEach(function(g){ codes[g.code]=codeName(g); });
  var codeOpts=opt("","All codes",S.f.code)+Object.keys(codes).sort().map(function(c){ return opt(c,c+(codes[c]?" · "+codes[c]:""),S.f.code); }).join("");
  var types=uniq(Object.keys(TYPE).map(function(c){return TYPE[c];}).concat(Object.keys(TYPE_PROPOSED).map(function(c){return TYPE_PROPOSED[c];}))).sort().concat(["Unclassified"]);
  var typeOpts=opt("","All types",S.f.type)+types.map(function(t){ return opt(t,t,S.f.type); }).join("");
  var stages=uniq(gs.map(function(g){ return g.stage; })).sort();
  var stageOpts=opt("","All stages",S.f.stage)+stages.map(function(s){ return opt(s,stageLbl(s),S.f.stage); }).join("");
  var stateOpts=[["active","Active (open + flagged)"],["open","Open"],["flag","Flagged"],["ack","Acknowledged"],["res","Resolved"],["all","All states"]].map(function(x){ return opt(x[0],x[1],S.f.state); }).join("");
  var anyF=S.f.type||S.f.code||S.f.stage||S.f.state!=="active";
  return '<div class="bar"><h1>Error Explorer</h1><span class="pill" data-tip="Acknowledge and Flag are kept in this browser tab only. Nothing is written to UBM until the backend endpoints exist.">Prototype · actions not saved</span>'+
    '<label>Customer <select id="cust">'+opts+'</select></label><label><select id="months">'+mo+'</select></label>'+
    '<span class="spacer"></span>'+
    '<button class="tog'+(S.all?" on":"")+'" id="all" data-tip="Show or hide every error indicator. Flagged errors stay visible.">'+'<span class="sw"></span>Errors '+(S.all?"on":"off")+'</button>'+
    '<div class="filters"><span class="flbl">Filter</span>'+
    '<select data-f="type">'+typeOpts+'</select><select data-f="code" style="max-width:260px">'+codeOpts+'</select>'+
    '<select data-f="stage">'+stageOpts+'</select><select data-f="state">'+stateOpts+'</select>'+
    (anyF?'<button class="btn link" id="clearf">Clear filters</button>':'')+'</div></div>';
}

function leftPane(sum,shown){
  var body;
  if(!M.customerId) body='<div class="empty">Pick a customer to load its locations.</div>';
  else if(M.locationsLoading) body='<div class="empty">Loading locations…</div>';
  else {
    var q=S.q.toLowerCase();
    var allLocs=M.locations||[]; if(allLocs.length&&String(allLocs[0].cust)!==String(M.customerId)) allLocs=[];
    var locs=allLocs.filter(function(l){ return !q || (String(l.name)+" "+(l.addr||"")+" "+(l.city||"")+" "+l.location_id).toLowerCase().indexOf(q)>=0; });
    locs.sort(function(a,b){ return ((sum[b.location_id]||{}).n||0)-((sum[a.location_id]||{}).n||0) || String(a.name).localeCompare(String(b.name)); });
    var html="";
    var none=sum.none;
    if(none&&S.all) html+='<div class="row muted" data-tip="Errors on bill blocks that are not mapped to any location (e.g. 3018), so they cannot be placed in the tree."><span class="caret"></span><span class="dot sev-'+sevKey(none.sev)+'"></span><span class="lbl"><div class="t">Unmapped bills</div><div class="s">No location to attach to</div></span><span class="cnt num">'+none.n+'</span></div>';
    locs.slice(0,400).forEach(function(l){
      var id=String(l.location_id), s=sum[id], sel=String(M.locationId)===id, n=s?s.n:0;
      var tip=s?("Open errors · highest severity "+s.sev+"\n")+Object.keys(s.codes).sort().map(function(c){ return c+"  "+nameOf(c)+"  ×"+s.codes[c]; }).join("\n"):"";
      html+='<div class="row'+(sel&&!S.sel?" sel":"")+'" data-loc="'+esc(id)+'"'+(tip?' data-tip="'+esc(tip)+'"':"")+'>'+
        '<span class="caret">'+(sel?"▼":"▶")+'</span><span class="dot'+(n&&S.all?" sev-"+sevKey(s.sev):" off")+'"></span>'+
        '<span class="lbl"><div class="t">'+esc(l.name)+'</div><div class="s">'+esc([l.btype,l.addr,l.city,l.state].filter(Boolean).join(" · "))+'</div></span>'+
        (n&&S.all?'<span class="cnt num">'+n+'</span>':'')+'</div>';
      if(sel) html+=hierarchyRows(shown);
    });
    if(locs.length>400) html+='<div class="empty">Showing 400 of '+locs.length+' locations. Narrow with search.</div>';
    if(!locs.length) html+='<div class="empty">No locations match.</div>';
    body=html;
  }
  var loadingSum = M.summaryLoading?'<span class="sub">counting errors…</span>':'';
  return '<div class="pane"><div class="pane-h"><b>Locations</b>'+loadingSum+'<span class="spacer"></span><input type="text" id="q" placeholder="Search" value="'+esc(S.q)+'" style="width:150px"></div><div class="scroll" data-keep="tree">'+body+'</div></div>';
}

// A solid dot = errors pinned at exactly this level; the count = every error
// underneath, so a parent row never repeats its children's dots.
function pinned(shown,level,test){ var keys=[], sev=0; shown.forEach(function(g){ if(g.place==="dot"&&DOT[g.code]===level&&test(g)){ keys.push(g.key); sev=Math.max(sev,g.maxSev); } }); return {keys:keys,sev:sev}; }
function under(shown,set){ return shown.filter(function(g){ return inSet(g,set); }).length; }
function dotHtml(p,what){ return p.keys.length?'<span class="dot hot sev-'+sevKey(p.sev)+'" data-pop="'+esc(p.keys.join(","))+'" data-tip="'+esc(p.keys.length+" "+what+"-level error(s). Click to review.")+'"></span>':'<span class="dot off"></span>'; }
function cntHtml(n,tip){ return n?'<span class="cnt num" data-tip="'+esc(tip)+'">'+n+'</span>':''; }
function caret(k){ return '<span class="caret" data-exp="'+esc(k)+'">'+(S.expanded[k]?"▼":"▶")+'</span>'; }

function hierarchyRows(shown){
  if(M.detailLoading) return '<div class="row l1 muted"><span class="lbl">Loading accounts…</span></div>';
  var t=tree(); if(!t.length) return '<div class="row l1 muted"><span class="lbl">No accounts paired to this location.</span></div>';
  var colors=acctColors(), wholeLoc=!S.sel;
  var byRecord={}; shown.forEach(function(g){ (byRecord[g.record_id]=byRecord[g.record_id]||[]).push(g); });
  var h="";
  t.forEach(function(a){
    var aset=setOf(a.vas), ak="a:"+a.key;
    var sel=S.sel&&S.sel.kind==="acct"&&S.sel.acct===a.key;
    var sw=wholeLoc?'<span class="swl" style="background:'+colors[a.key]+'" data-tip="This account\'s line on the chart"></span>':'';
    h+='<div class="row l1'+(sel?" sel":"")+'" data-acct="'+esc(a.key)+'">'+caret(ak)+
      dotHtml(pinned(shown,"account",function(g){ return g.acctKeys.indexOf(a.key)>=0; }),"Account")+sw+
      '<span class="lbl"><div class="t">'+esc(a.key)+'</div><div class="s">Account · '+esc(Object.keys(a.comms).join(", "))+'</div></span>'+
      cntHtml(under(shown,aset),"Errors on this account")+'</div>';
    if(!S.expanded[ak]) return;
    a.vorder.forEach(function(v){
      var vset=setOf(v.vas), vk="v:"+v.key;
      var vsel=S.sel&&S.sel.kind==="vend"&&S.sel.vend===v.key;
      h+='<div class="row l2'+(vsel?" sel":"")+'" data-vend="'+esc(v.key)+'" data-acctof="'+esc(a.key)+'" data-name="'+esc(v.name)+'">'+caret(vk)+
        dotHtml(pinned(shown,"vendor",function(g){ return inSet(g,vset); }),"Vendor")+
        '<span class="lbl"><div class="t">'+esc(v.name)+'</div><div class="s">Vendor</div></span>'+cntHtml(under(shown,vset),"Errors on this vendor's bills")+'</div>';
      if(!S.expanded[vk]) return;
      v.vas.forEach(function(m){
        var one={}; one[m.va_id]=true; var mk="m:"+m.va_id;
        var msel=S.sel&&S.sel.kind==="meter"&&String(S.sel.va)===String(m.va_id);
        h+='<div class="row l3'+(msel?" sel":"")+'" data-va="'+esc(m.va_id)+'" data-acctof="'+esc(a.key)+'">'+caret(mk)+
          dotHtml(pinned(shown,"meter",function(g){ return inSet(g,one); }),"Meter")+
          '<span class="lbl"><div class="t">'+esc(m.meter_serial||"No meter id")+'</div><div class="s">Meter · '+esc([m.commodity,m.client_account,m.closed?"Closed":""].filter(Boolean).join(" · "))+'</div></span>'+
          cntHtml(under(shown,one),"Errors on this meter")+'</div>';
        if(!S.expanded[mk]) return;
        var bl=bills().filter(function(b){ return String(b.va_id)===String(m.va_id); }).sort(function(x,y){ return String(y.start_d).localeCompare(String(x.start_d)); });
        var seen={}; bl=bl.filter(function(b){ var k=b.record_id; if(seen[k]) return false; seen[k]=true; return true; });
        if(!bl.length) h+='<div class="row l4 muted"><span class="lbl"><div class="s">No bills in this window</div></span></div>';
        bl.slice(0,12).forEach(function(b){
          var gsB=(byRecord[b.record_id]||[]).filter(function(g){ return inSet(g,one); });
          var sev=gsB.reduce(function(x,g){ return Math.max(x,g.maxSev); },0);
          var amt=num(b.charges)!=null?num(b.charges):num(b.bill_total);
          h+='<div class="row l4'+(gsB.length?"":" muted")+'"'+(gsB.length?' data-pop="'+esc(gsB.map(function(g){return g.key;}).join(","))+'" data-tip="'+esc(gsB.map(function(g){ return g.code+"  "+codeName(g); }).join("\n")+"\nClick to review")+'"':'')+'>'+
            '<span class="caret"></span>'+(gsB.length?'<span class="dot sev-'+sevKey(sev)+'"></span>':'<span class="dot off"></span>')+
            '<span class="lbl"><div class="t">Bill '+esc(b.bill_id||("record "+b.record_id))+'</div><div class="s">'+esc(fmtD(day(b.start_d))+" – "+fmtD(day(b.end_d))+(amt!=null?" · "+fmtV(amt,"$"):""))+'</div></span>'+
            cntHtml(gsB.length,"Errors on this bill")+'</div>';
        });
        if(bl.length>12) h+='<div class="row l4 muted"><span class="lbl"><div class="s">'+(bl.length-12)+' older bills not listed</div></span></div>';
      });
    });
  });
  return h;
}

function scopeLabel(){
